<script setup lang="ts">
import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import {Search,ArrowUpRight} from 'lucide-vue-next';import type {Loan,Page} from '../api';import {useLoans} from '../composables/poll';import {money} from '../money';import DataState from '../components/DataState.vue';import StatusBadge from '../components/StatusBadge.vue';
const search=ref('');const page=ref(1);const router=useRouter();const path=computed(()=>`/loans?search=${encodeURIComponent(search.value)}&page=${page.value}&pageSize=25`);const {data,error,loading,updatedAt}=useLoans<Page<Loan>>(path);
</script>
<template><div class="page-title"><div><p class="eyebrow">THE LOAN BOOK</p><h1>Loans</h1><p class="muted">Contractual schedules alongside actual posted balances.</p></div><RouterLink to="/loans/LOAN-1001" class="action-link">Example loan <ArrowUpRight :size="17"/></RouterLink></div><DataState :loading="loading" :error="error" :updated-at="updatedAt"/><section class="panel"><div class="panel-heading"><h3>Fictional customers <span class="count-pill">{{data?.total??'—'}}</span></h3><el-input v-model="search" placeholder="Search customer or loan reference" clearable class="search" @input="page=1"><template #prefix><Search :size="16"/></template></el-input></div><el-table :data="data?.items??[]" @row-click="(row:Loan)=>router.push('/loans/'+row.reference)" class="clickable-table"><el-table-column label="Customer / reference" min-width="210"><template #default="{row}"><strong>{{row.customer}}</strong><small class="table-sub">{{row.reference}}</small></template></el-table-column><el-table-column label="Actual principal" min-width="180"><template #default="{row}">{{money(row.outstandingPrincipal)}}</template></el-table-column><el-table-column label="Annual rate" width="120"><template #default="{row}">{{(row.annualRate*100).toFixed(2)}}%</template></el-table-column><el-table-column prop="nextDueDate" label="Next due date" width="150"/><el-table-column label="Due at 31 Oct" min-width="160"><template #default="{row}">{{money(row.dueAmount)}}</template></el-table-column><el-table-column label="Status" width="130"><template #default="{row}"><StatusBadge :status="row.status"/></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="25" :total="data?.total??0" layout="prev,pager,next,total"/><p class="chart-note">THB only. Eligibility uses bank paidAt in Asia/Bangkok. Amounts beyond due installments remain unapplied credit.</p></section></template>
